import json

def decode(request):
    if request['occurred_ms'] <= 0:
        raise ValueError('invalid occurred_ms')
    value = json.loads(request['data_json'])
    items, deleted = value.get('items', []), value.get('deleted_ids', [])
    if not isinstance(items, list) or not isinstance(deleted, list):
        raise ValueError('invalid batch')
    for item in items:
        if item['end_ms'] < item['start_ms']:
            raise ValueError('invalid sample time')
    return items, deleted

