class Store:
    def __init__(self): self.writes = 0; self.bytes = 0
    def put(self, key, value): self.writes += 1; self.bytes += len(value)

class Runner:
    def __init__(self): self.seen = set(); self.executions = 0
    def run(self, delivery_id):
        if delivery_id not in self.seen:
            self.seen.add(delivery_id); self.executions += 1

def deliver(event_id, subscriptions, store, runner, extra_state=False):
    store.put('receipt:'+event_id, b'received')
    if extra_state:
        for phase in ('claim', 'done'): store.put('source:'+phase, b'1')
    for sub in subscriptions:
        if extra_state:
            for stage in ('published', 'attempt'):
                for phase in ('claim', 'done'): store.put(sub+stage+phase, b'1')
        runner.run(event_id+':'+sub)

def send_with_retries(send):
    for outer in range(3):
        for sdk in range(3):
            try: return send()
            except TimeoutError: pass
    raise TimeoutError('exhausted')

def scan(owners, replicas):
    return sum(1 for replica in range(replicas) for owner in owners)

